        vm.prank(authorizedSender);
        bool success = ebu.transfer(recipients, amounts);

        // Check that the function returns true despite failed low-level calls
        assertTrue(success);

        // Verify state was incorrectly updated despite failed transfers
        // Note: Contract multiplies amounts by 1e18 internally
        uint expectedAmount1 = 1 ether;
        uint expectedAmount2 = 2 ether;

